package com.Akeltroll.dragonsofberk.network.message;

import com.Akeltroll.dragonsofberk.config.FlightSpeedSync;
import java.util.function.Supplier;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.network.NetworkEvent;

public class MessageSyncFlightSpeed {
    private final double climbRatio;
    private final double descentRatio;
    private final double sprintMultiplier;

    public MessageSyncFlightSpeed(double climbRatio, double descentRatio, double sprintMultiplier) {
        this.climbRatio = climbRatio;
        this.descentRatio = descentRatio;
        this.sprintMultiplier = sprintMultiplier;
    }

    public static void encode(MessageSyncFlightSpeed msg, FriendlyByteBuf buf) {
        buf.writeDouble(msg.climbRatio);
        buf.writeDouble(msg.descentRatio);
        buf.writeDouble(msg.sprintMultiplier);
    }

    public static MessageSyncFlightSpeed decode(FriendlyByteBuf buf) {
        return new MessageSyncFlightSpeed(buf.readDouble(), buf.readDouble(), buf.readDouble());
    }

    public static void handle(MessageSyncFlightSpeed msg, Supplier<NetworkEvent.Context> ctxSupplier) {
        NetworkEvent.Context ctx = ctxSupplier.get();
        ctx.enqueueWork(() -> FlightSpeedSync.accept(msg.climbRatio, msg.descentRatio, msg.sprintMultiplier));
        ctx.setPacketHandled(true);
    }
}

